ST.xhtml:
GVL.fbServo();

IF GVL.Control.CalibrationMode THEN
	// В режиме калибровки берем исходное нескорректированное значение момента от датчика в Нм
	GVL.rActualTension := GVL.rTorque;
ELSE
	// В обычном режиме значение момента скорректированное (линеаризованное) в Нм
	GVL.rActualTension := GVL.rTorqueCalibrated;
END_IF

// Задание момента приходит от АРМ в виде целого числа со знаком * 500. Пример: получаем по модбас 5000 => задание = 10.0 Нм
GVL.rSetValue := TO_REAL(TO_INT(MODBUS_DATA.MB_TORQUE_SV)) / PID_SET_POINT_scale_;

fbPID(
	ACTUAL := GVL.rActualTension,
	SET_POINT := GVL.rSetValue,
	KP := GVL.KP,
	TN := GVL.KI,
	TV := GVL.KD,
	Y_MANUAL := 0,
	Y_OFFSET := 0,
	Y_MIN := GVL.rYMin,
	Y_MAX := GVL.rYMax,
	MANUAL := FALSE,
	RESET := FALSE,
	Y=> GVL.rY,
	LIMITS_ACTIVE=> ,
	OVERFLOW=> );

GVL.lrFollowVelocity := TO_LREAL(GVL.rY * PID_OUT_scale_);
